import json,urllib.request,ssl,base64
API_URL=open('.env').read().strip().split(chr(61),1)[1]
ctx=ssl.create_default_context()
records=json.loads(base64.b64decode('').decode())
body=json.dumps({"action":"import","records":records}).encode()
req=urllib.request.Request(API_URL,data=body,method='POST',headers={"Content-Type":"text/plain"})
with urllib.request.urlopen(req,context=ctx) as res:
    print('Result:',json.loads(res.read()))
